/*
Client runtime ownership
- Default and Vapor entries resolve the same runtime for the active DOM bridge.
- Explicit createRue() calls still create independent runtime instances.
- Runtime DOM binding and error-bridge installation happen on one path.
*/

import { createRue as createRueRuntime } from '@rue-js/runtime-vapor'
import { BrowserDOMAdapter, registerDOMBridgeConsumer, setDOMAdapter } from './dom'
import { dispatchErrorCaptured, wasErrorCapturedDispatched } from './error-capture'
import { runWithRuntime } from './runtime-context'
import type { Rue } from './runtime-types'

const RUE_CLIENT_RUNTIME_CACHE_KEY = '__rue_client_runtime_by_dom_bridge__'
const RUE_JS_ERROR_BRIDGE_KEY = '__rue_js_error_bridge_installed'

type ClientRuntimeGlobal = typeof globalThis & {
  __rue?: Rue
  __rue_dom?: unknown
  __rue_runtime_vapor_shared_bridge?: {
    popCurrentContainer?(): void
    pushCurrentContainer?(container: unknown): void
  }
  [RUE_CLIENT_RUNTIME_CACHE_KEY]?: WeakMap<object, Rue>
}

const clientRuntimeGlobal = globalThis as ClientRuntimeGlobal
const runtimeDOMBridgeByInstance = new WeakMap<object, unknown>()
const registeredDOMBridgeConsumers = new WeakSet<object>()
const runtimeErrorHandlers = new WeakMap<object, Set<(error: any, instance?: any) => void>>()

const canTrackRuntime = (runtime: unknown): runtime is object =>
  (typeof runtime === 'object' || typeof runtime === 'function') && runtime != null

const getRuntimeCache = () =>
  (clientRuntimeGlobal[RUE_CLIENT_RUNTIME_CACHE_KEY] ??= new WeakMap<object, Rue>())

const getClientDOMBridge = (): object => {
  if (!canTrackRuntime(clientRuntimeGlobal.__rue_dom)) {
    setDOMAdapter(new BrowserDOMAdapter())
  }
  return clientRuntimeGlobal.__rue_dom as object
}

const installRuntimeErrorBridge = <T>(runtime: T): T => {
  if (!canTrackRuntime(runtime)) {
    return runtime
  }

  ;(
    globalThis as typeof globalThis & {
      __rue_dispatch_error_captured?: (error: any, instance?: any, info?: string) => boolean
    }
  ).__rue_dispatch_error_captured = (error, instance, info) =>
    wasErrorCapturedDispatched(error) ? false : dispatchErrorCaptured(error, instance, info)

  if ((runtime as Record<string, unknown>)[RUE_JS_ERROR_BRIDGE_KEY]) {
    return runtime
  }

  const handlers = new Set<(error: any, instance?: any) => void>()
  runtimeErrorHandlers.set(runtime, handlers)

  const runtimeWithErrorHandler = runtime as { handleError?: (error: any, instance?: any) => void }
  const originalHandleError =
    typeof runtimeWithErrorHandler.handleError === 'function'
      ? runtimeWithErrorHandler.handleError.bind(runtime)
      : null

  ;(runtime as { onError?: unknown }).onError = (fn: (error: any, instance?: any) => void) => {
    if (typeof fn !== 'function') {
      return undefined
    }

    handlers.add(fn)
    return () => {
      handlers.delete(fn)
    }
  }

  ;(runtime as { handleError?: unknown }).handleError = (error: any, instance?: any) => {
    if (!wasErrorCapturedDispatched(error) && dispatchErrorCaptured(error, instance)) {
      return false
    }

    if (originalHandleError) {
      try {
        originalHandleError(error, instance)
      } catch {}
    } else if (handlers.size === 0) {
      try {
        ;(console as any).error?.(error)
      } catch {}
    }

    handlers.forEach(handler => {
      try {
        handler(error, instance)
      } catch {}
    })

    return true
  }

  ;(runtime as Record<string, unknown>)[RUE_JS_ERROR_BRIDGE_KEY] = true
  return runtime
}

/** Read the DOM bridge currently bound to a runtime. */
export const getMarkedRuntimeDOMBridge = (runtime: unknown) => {
  if (!canTrackRuntime(runtime)) {
    return undefined
  }
  return runtimeDOMBridgeByInstance.get(runtime)
}

/** Mark a runtime as synchronized with a DOM bridge and subscribe it to bridge updates. */
export const markRuntimeDOMBridge = (runtime: unknown, bridge: unknown) => {
  if (!canTrackRuntime(runtime)) {
    return
  }
  runtimeDOMBridgeByInstance.set(runtime, bridge)
  if (!registeredDOMBridgeConsumers.has(runtime)) {
    registeredDOMBridgeConsumers.add(runtime)
    registerDOMBridgeConsumer(runtime)
  }
}

/** Ensure an explicit or shared runtime is bound to the current DOM bridge. */
/*
 * [RUE-MOUNT-021] 应用挂载 · 步骤 21：ensureRuntimeDOMBridge(runtime)
 * 对应指南：RUE_SOURCE_GUIDE.html#flow=mount&view=sequence&node=21
 * 所在阶段：B · 开始挂载：解析容器 → 执行 runner；节点类型：调用。
 *   1. 先检查 runtime.setDOMAdapter 是不是函数。如果没有这个能力，函数直接返回。
 *   2. 取得当前 bridge，与 getMarkedRuntimeDOMBridge(runtime) 记录的对象比较；严格相等时说明已同步，直接返回。
 *   3. 如果不同，调用 runtimeWithDOM.setDOMAdapter(bridge)，再 markRuntimeDOMBridge(runtime, bridge) 更新记录和订阅状态。
 * 执行结果：已有正确绑定时这里只做检查；需要更新时才改变适配器。随后返回 runWithClientRuntime 继续切换活动 runtime。
 * 衔接说明：确认 runtime 绑定当前 DOM bridge。已绑定同一 bridge 则直接返回；否则 setDOMAdapter 并登记绑定。
 * 断点观察：对比记录的 bridge 与当前 bridge 的对象身份，确认是否实际执行了 setDOMAdapter。
 */
export const ensureRuntimeDOMBridge = (runtime: unknown) => {
  const runtimeWithDOM = runtime as { setDOMAdapter?: (bridge: unknown) => void } | null | undefined
  if (typeof runtimeWithDOM?.setDOMAdapter !== 'function') {
    return
  }
  const bridge = getClientDOMBridge()
  if (getMarkedRuntimeDOMBridge(runtime) === bridge) {
    return
  }
  runtimeWithDOM.setDOMAdapter(bridge)
  markRuntimeDOMBridge(runtime, bridge)
}

/** Create an independent client runtime without adding it to the default bridge cache. */
/*
 * [RUE-MOUNT-003] 应用挂载 · 步骤 3：createClientRuntime() → createRueRuntime(bridge)
 * 对应指南：RUE_SOURCE_GUIDE.html#flow=mount&view=sequence&node=3
 * 所在阶段：A · 创建时：appRue 和 mount 的来源；节点类型：调用。
 *   1. client-runtime.ts 顶部有 import { createRue as createRueRuntime } from '@rue-js/runtime-vapor'，所以源码中调用的是 runtime-vapor 包导出的 createRue。
 *   2. 进入 createClientRuntime 时，先执行 getClientDOMBridge()，得到当前 DOM 适配器 bridge。
 *   3. 随后执行 createRueRuntime(bridge)。这一步会调用 runtime-vapor/index.js 中已经创建好的 createRue 工厂。
 *   4. 这个工厂之所以已经存在，是因为浏览器加载 @rue-js/runtime-vapor 模块时，index.js 顶层代码已经执行了 createRuntimeEntry(...)。
 *   5. 所以这里的真实关系是：模块加载阶段先 createRuntimeEntry(...) 得到 createRueRuntime；运行阶段 createClientRuntime() 再调用 createRueRuntime(bridge)。
 *   6. createRueRuntime(bridge) 返回 runtime 对象后，外层再包 installRuntimeErrorBridge(...)，然后 markRuntimeDOMBridge(runtime, bridge)。
 * 执行结果：createClientRuntime 拿到一个已经过 runtime-vapor 包装逻辑处理的 runtime 实例，并把它与当前 DOM bridge 绑定。下一格展示的是这个导入工厂的来源，不是 createClientRuntime 函数体内的下一条同步调用。
 * 衔接说明：以下创建步骤仅在创建新 runtime 时发生。这里调用的 createRueRuntime 是从 @rue-js/runtime-vapor 导入的工厂，它在模块加载时已由 createRuntimeEntry(...) 生成。
 * 断点观察：看 client-runtime.ts 顶部 import 的 createRueRuntime，再看源码中 createRueRuntime(bridge)。如果想追工厂来源，要跳到 runtime-vapor/dist/index.js 顶层的 createRuntimeEntry(...)，而不是只在 createClientRuntime 函数体里找。
 */
export const createClientRuntime = (): Rue => {
  const bridge = getClientDOMBridge()
  const runtime = installRuntimeErrorBridge(createRueRuntime(bridge) as Rue)
  markRuntimeDOMBridge(runtime, bridge)
  return runtime
}

/** Get the one default client runtime associated with the current DOM bridge. */
/*
 * [RUE-MOUNT-002] 应用挂载 · 步骤 2：getClientRuntime()：查找当前 DOM bridge 的缓存
 * 对应指南：RUE_SOURCE_GUIDE.html#flow=mount&view=sequence&node=2
 * 所在阶段：A · 创建时：appRue 和 mount 的来源；节点类型：条件。
 *   1. 源码中 getClientDOMBridge() 取得当前 DOM 适配器对象 bridge。如果全局 __rue_dom 还不是非空对象或函数，辅助函数会先安装 BrowserDOMAdapter。bridge 是对象本身，不是 #app 容器，也不是字符串。
 *   2. 源码中 getRuntimeCache() 取得保存在全局的 WeakMap；第一次调用时才创建这个 Map。源码中以 bridge 的对象身份作为 key，查找与当前适配器关联的默认 runtime。
 *   3. 情况一：cache.get(bridge) 命中。runtime 已有值，源码中的 !runtime 为 false，跳过 __rue 回退；源码中也为 false，进入 else 检查错误桥和 DOM 绑定。
 *   4. 情况二：缓存未命中，但全局 __rue 是非空对象或函数。源码中条件成立，把 __rue 的引用赋给 runtime，再进入源码中的复用分支。canTrackRuntime 这里只检查是否能当对象追踪，没有完整校验 Rue 接口。
 *   5. 情况三：缓存没有命中，也没有可追踪的 __rue。runtime 仍为空，源码中成立，调用 createClientRuntime()。下面的实例创建和方法包装步骤只在这条分支发生。
 *   6. 复用分支中，installRuntimeErrorBridge(runtime) 保证错误转发已安装；ensureRuntimeDOMBridge(runtime) 检查适配器身份，必要时重新绑定。它们不是再次创建 runtime。
 * 执行结果：三条路径汇合后，函数尾部执行 cache.set(bridge, runtime)、更新全局 __rue，再 return runtime。返回的是同一个实例引用，由上一节点的 appRue 接住；本片段没有显示的尾部可以在“完整源码”里查看。
 * 衔接说明：有缓存或已有 __rue 时复用；只有两者都没有，才执行下面 A03–A08 的创建过程。
 * 断点观察：依次看 bridge、cache.get(bridge)、clientRuntimeGlobal.__rue 和 runtime。单步经过第 158 或 161 行，确认这次走的是复用还是创建；复用路径不要继续把创建节点当作必经步骤。
 */
export const getClientRuntime = (): Rue => {
  const bridge = getClientDOMBridge() //) 取得当前 DOM 适配器对象 bridge。它先尝试复用，只有找不到可用对象时才创建。
  const cache = getRuntimeCache()
  let runtime = cache.get(bridge)

  if (!runtime && canTrackRuntime(clientRuntimeGlobal.__rue)) {
    runtime = clientRuntimeGlobal.__rue as Rue
  }
  if (!runtime) {
    runtime = createClientRuntime()
  } else {
    installRuntimeErrorBridge(runtime)
    ensureRuntimeDOMBridge(runtime)
  }

/*
 * [RUE-MOUNT-010] 应用挂载 · 步骤 10：getClientRuntime() 返回同一个对象 → appRue 接住
 * 对应指南：RUE_SOURCE_GUIDE.html#flow=mount&view=sequence&node=10
 * 所在阶段：A · 创建时：appRue 和 mount 的来源；节点类型：返回。
 *   1. cache.set(bridge, runtime) 把当前适配器对象与选出的运行时关联起来，方便下次按 bridge 查找。
 *   2. clientRuntimeGlobal.__rue = runtime 更新全局默认引用。这是再次保存引用，没有复制 runtime。
 *   3. return runtime 退出 getClientRuntime，回到 useApp 中 appRue 的初始化表达式。
 * 执行结果：appRue 接收到这个 runtime。正常的新建路径中，它的 mount 已经过包装；复用路径则沿用已有实例。
 * 衔接说明：因此 appRue 是 runtime 对象；appRue.mount 是包装函数。已有缓存时，上面的对象创建和包装已经发生过。
 * 断点观察：确认 appRue、cache.get(bridge) 与 clientRuntimeGlobal.__rue 的引用相等。
 */
  cache.set(bridge, runtime)
  clientRuntimeGlobal.__rue = runtime
  return runtime
}

/** Activate a client runtime/container pair and restore both outer contexts afterward. */
/*
 * [RUE-MOUNT-020] 应用挂载 · 步骤 20：runWithClientRuntime(runtime, runner, container)
 * 对应指南：RUE_SOURCE_GUIDE.html#flow=mount&view=sequence&node=20
 * 所在阶段：B · 开始挂载：解析容器 → 执行 runner；节点类型：调用。
 *   1. runtime 接收 appRue；container 接收 el；runner 接收上一步的 mountRunner 箭头函数。
 *   2. 函数先执行 ensureRuntimeDOMBridge(runtime)，确保接下来的操作使用当前适配器。
 *   3. 然后调用 runWithRuntime(runtime, 另一个箭头函数)，把运行时切换和容器处理分两层完成。
 * 执行结果：runner 仍未执行。下一步先检查 DOM 绑定，再进入第二层上下文包装。
 * 衔接说明：参数对应：runtime = appRue；runner = mountRunner；container = el。
 * 断点观察：检查 runtime === appRue、container === el，并区分 runner 函数与 runtime 对象。
 */
export const runWithClientRuntime = <T>(runtime: Rue, runner: () => T, container?: unknown): T => {
  /*
   * [03 绑定运行时上下文]
   * 调用链：useApp.mount() -> runWithClientRuntime() -> runWithRuntime() -> runner()。
   * 观察：runtime、container、bridge、didPush。
   */
  // oxlint-disable-next-line no-debugger -- Rue 源码学习用自动断点。
  if ((globalThis as any).__RUE_RENDER_DEBUG__?.take('03.runtime-context')) debugger
  ensureRuntimeDOMBridge(runtime)
/*
 * [RUE-MOUNT-022] 应用挂载 · 步骤 22：runWithRuntime(runtime, 内部箭头函数)
 * 对应指南：RUE_SOURCE_GUIDE.html#flow=mount&view=sequence&node=22
 * 所在阶段：B · 开始挂载：解析容器 → 执行 runner；节点类型：传回调。
 *   1. 外层原有 runner 是 useApp.ts 传入的 mountRunner。
 *   2. 这次新传入的箭头函数位于 client-runtime.ts，负责 pushCurrentContainer、执行外层 runner，以及 finally 中的 popCurrentContainer。
 *   3. 讲解把新箭头函数叫作 contextRunner。它捕获外层 runner 和 container，但传入函数时仍不会执行函数体。
 * 执行结果：runWithRuntime 的 runner 形参接收到 contextRunner；它内部的 runner() 会先进入容器上下文代码。
 * 衔接说明：又传入一个函数：它负责容器入栈并调用外层 runner。下文称它为 contextRunner。它与 mountRunner 是两个函数。
 * 断点观察：从调用栈逐层看 runner 的函数位置：runWithRuntime 中指向 client-runtime.ts，外层则指向 useApp.ts。
 */
  return runWithRuntime(runtime, () => {
/*
 * [RUE-MOUNT-024] 应用挂载 · 步骤 24：runWithRuntime 中的 runner() → contextRunner
 * 对应指南：RUE_SOURCE_GUIDE.html#flow=mount&view=sequence&node=24
 * 所在阶段：B · 开始挂载：解析容器 → 执行 runner；节点类型：执行回调。
 *   1. 读取共享 bridge：__rue_runtime_vapor_shared_bridge。它提供当前容器栈等协作能力，与前面用作缓存 key 的 DOM bridge 不是同一个变量来源。
 *   2. didPush 需要同时满足 container 非空和 bridge.pushCurrentContainer 是函数。
 *   3. 条件成立时把 el 压入当前容器栈；不成立就跳过入栈，但仍会执行下面 try 中的原始 runner。
 * 执行结果：容器上下文准备好后，下一次 runner() 将进入 useApp.ts 的 mountRunner。
 * 衔接说明：返回到 client-runtime.ts 的内部箭头函数，满足 didPush 条件时先把 el 压入当前容器栈。
 * 断点观察：观察 bridge、didPush、container；确认本次是否真的调用了 pushCurrentContainer。
 */
    const bridge = clientRuntimeGlobal.__rue_runtime_vapor_shared_bridge
    const didPush = container != null && typeof bridge?.pushCurrentContainer === 'function'
    if (didPush) {
      bridge.pushCurrentContainer!(container)
    }
    try {
      console.log('第二个打印出来')
/*
 * [RUE-MOUNT-025] 应用挂载 · 步骤 25：runWithClientRuntime 中的 runner() → mountRunner
 * 对应指南：RUE_SOURCE_GUIDE.html#flow=mount&view=sequence&node=25
 * 所在阶段：B · 开始挂载：解析容器 → 执行 runner；节点类型：执行回调。
 *   1. 通过闭包读取外层 runner，拿到 useApp.ts 中的 mountRunner。
 *   2. 同步执行这个函数，进入它的函数体，而不是再次进入 runWithRuntime。
 *   3. return 会转交 runner 的返回值；但在离开当前 try/finally 前，还必须执行容器出栈清理。
 * 执行结果：控制流回到 useApp.ts 的箭头函数，开始读取并调用 appRue.mount(App, el)。
 * 衔接说明：这次 runner 是 useApp.ts 传入的那个箭头函数。下一行回到它的函数体。
 * 断点观察：对 runner() 使用单步进入，函数位置应落到 useApp.ts，而不是当前文件里另一处同名 runner。
 */
      return runner()
    } finally {
      if (didPush) {
/*
 * [RUE-MOUNT-101] 应用挂载 · 步骤 101：runWithClientRuntime finally：popCurrentContainer()
 * 对应指南：RUE_SOURCE_GUIDE.html#flow=mount&view=sequence&node=101
 * 所在阶段：F · 提交 #app → 生命周期 → 逐层返回；节点类型：返回。
 *   1. 只有之前 didPush 为 true，才尝试调用 bridge?.popCurrentContainer?.()。
 *   2. 它与之前 pushCurrentContainer(el) 配对，恢复外层容器；没有入栈就不应该额外弹栈。
 *   3. 弹出当前容器不会移除已经挂载的 DOM，也不会清空 containerRef，只是结束临时执行上下文。
 * 执行结果：contextRunner 结束，回到 runWithRuntime，然后执行它自己的 finally。
 * 衔接说明：若先前确实入栈，这里弹出 el。随后 contextRunner 返回到 runWithRuntime。
 * 断点观察：对照 didPush 的原始值，查看共享 bridge 当前容器在出栈前后的变化。
 */
        bridge?.popCurrentContainer?.()
      }
    }
  })
}
